// ListUsersIter returns an iterator that iterates
// over the results of ListUsers.
//
// For example:
//
//	for item, err := range c.ListUsersIter(ctx, &ListUsersRequest{}) {
//	  if err != nil {
//	    return err
//	  }
//	  fmt.Println(item)
//	}
//
// Options opts are passed to each ListUsers call
// made by the iterator under the hood.
//
// Callers who need custom pagination logic should use
// ListUsers directly.
func (c *internalClient) ListUsersIter(ctx context.Context, req *ListUsersRequest, opts ...call.Option) iter.Seq2[*User, error] {
	return func(yield func(*User, error) bool) {
		// Copy the request so advancing the pagination field does not mutate the
		// caller's struct. Other reference-bearing fields are shared and must remain read-only.
		pageReq := ListUsersRequest{}
		if req != nil {
			pageReq = *req
		}
		for {
			resp, err := c.ListUsers(ctx, &pageReq, opts...)
			if err != nil {
				yield(nil, err)
				return
			}
			items := resp.Resources
			for i := range items {
				if !yield(&items[i], nil) {
					return
				}
			}
			if len(items) == 0 {
				return
			}
			nextOffset := int64(len(items))
			if resp.StartIndex != nil {
				nextOffset += *resp.StartIndex
			}
			pageReq.StartIndex = new(nextOffset)
		}
	}
}

